import{_ as e,o,c as n,a2 as r}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/es/workflows-detalhe.png",t="/pro-agent-hub-installer/capturas/es/workflows-fluxo.png",l="/pro-agent-hub-installer/capturas/es/workflows-codigo.png",c="/pro-agent-hub-installer/capturas/es/workflows-versoes.png",i="/pro-agent-hub-installer/capturas/es/execucoes-lista.png",d="/pro-agent-hub-installer/capturas/es/execucoes-detalhe.png",j=JSON.parse('{"title":"Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/workflows.md","filePath":"es/interface/workflows.md","lastUpdated":1787856241000}'),u={name:"es/interface/workflows.md"};function p(g,a,m,h,f,b){return o(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h1><p>Un <strong>workflow</strong> es una automatización: una secuencia de pasos que la plataforma ejecuta sola — a mano, por agendamiento o llamada desde otro sitio.</p><p>Hay dos tipos, elegidos con un par de botones en la pestaña General:</p><ul><li><strong>Low-code</strong> — un flujo dibujado en cajas conectadas.</li><li><strong>High-code</strong> — un archivo Python.</li></ul><p>El tipo se puede cambiar en cualquier momento, y <strong>los dos contenidos quedan guardados</strong>: pasar a high-code no borra el flujo dibujado, y volver a low-code no borra el código. Lo que cambia es cuál de los dos ejecuta la plataforma — y qué pestaña aparece.</p><div class="tip custom-block"><p class="custom-block-title">El co-pilot escribe los dos</p><p>El botón de Pegasus, en la pestaña General, acepta un pedido en lenguaje natural y devuelve o un flujo, o el Python — y la plataforma reconoce lo que vino, cambia el tipo y deja el resultado en la pestaña correcta. Es el camino más corto para salir de cero, y también para pedir &quot;convierte este flujo en código&quot;.</p></div><h2 id="pestana-general" tabindex="-1">Pestaña General <a class="header-anchor" href="#pestana-general" aria-label="Permalink to &quot;Pestaña General&quot;">​</a></h2><p><img src="'+s+'" alt="workflows-detalhe"></p><p>Descripción, grupo y el <strong>agendamiento</strong>.</p><p>El agendamiento es una <strong>expresión cron</strong>, evaluada en UTC. La pantalla muestra las próximas ejecuciones calculadas a partir de la expresión — compruébalas ahí antes de guardar; es más rápido que descubrir al día siguiente que la hora estaba desplazada.</p><div class="tip custom-block"><p class="custom-block-title">Un workflow agendado nunca se solapa consigo mismo</p><p>Si llega la hora y la ejecución anterior sigue corriendo, el disparo se <strong>ignora</strong> y queda registrado como tal. Es la garantía de que un proceso agendado nunca corre dos veces a la vez. Las ejecuciones manuales no tienen ese candado.</p></div><p>El <strong>nivel de log</strong> define cuánto graba la ejecución: solo errores, el avance, o todo. Un log detallado ayuda a depurar y pesa en la base — las ejecuciones antiguas se podan por la retención configurada en <a href="/pro-agent-hub-installer/es/interface/administracao#configuración">Configuración</a>.</p><h2 id="pestana-flujo-low-code" tabindex="-1">Pestaña Flujo (low-code) <a class="header-anchor" href="#pestana-flujo-low-code" aria-label="Permalink to &quot;Pestaña Flujo (low-code)&quot;">​</a></h2><p><img src="'+t+'" alt="workflows-fluxo"></p><p>El lienzo donde se monta el flujo. Arrastra los nodos de la paleta, conecta las salidas a las entradas y haz clic en un nodo para configurarlo.</p><p>Los tipos de nodo cubren entrada y salida, condición, bucle, llamada a un agente, equipo o planificador, operaciones de datos y sistema, y un nodo de <strong>script</strong> para lo que no encaje en los demás.</p><p><strong>Ejecución en vivo.</strong> Al correr desde el botón de prueba, el lienzo acompaña:</p><ul><li>el nodo en ejecución <strong>late, con el borde destacado</strong>;</li><li>al terminar, cambia de color según el resultado y muestra <strong>cuánto tardó</strong>;</li><li>los que aún no corrieron quedan apagados.</li></ul><p>Esto ocurre <strong>durante</strong> la ejecución, nodo a nodo, y no solo al final. En un flujo largo, es como se ve dónde está atascado.</p><h2 id="pestana-codigo-high-code" tabindex="-1">Pestaña Código (high-code) <a class="header-anchor" href="#pestana-codigo-high-code" aria-label="Permalink to &quot;Pestaña Código (high-code)&quot;">​</a></h2><p><img src="'+l+'" alt="workflows-codigo"></p><p>Un editor Python con autocompletado de las funciones de la plataforma — escribe <code>db_</code> y aparece la lista, con la firma y la descripción de cada una.</p><p>El código corre con un ámbito ya montado: <code>context</code> (lo que entró), <code>log()</code>, <code>is_cancelled()</code> y las operaciones de datos, sistema e integración. No hace falta ningún <code>import</code> para usarlas. La referencia completa está en <a href="/pro-agent-hub-installer/es/funcoes/workflow_highcode">Workflow high-code</a>.</p><div class="tip custom-block"><p class="custom-block-title">Un workflow largo debe comprobar la cancelación</p><p>La cancelación es <strong>cooperativa</strong>: la plataforma anota el pedido, y es tu código el que decide parar. En un bucle largo, llama a <code>is_cancelled()</code> en cada vuelta y sal cuando devuelva verdadero. Sin eso, cancelar solo surte efecto cuando la ejecución termina por su cuenta.</p></div><h2 id="pestana-ejecuciones" tabindex="-1">Pestaña Ejecuciones <a class="header-anchor" href="#pestana-ejecuciones" aria-label="Permalink to &quot;Pestaña Ejecuciones&quot;">​</a></h2><p>El historial de ese workflow, con situación, duración y el log de cada ejecución.</p><h2 id="pestana-versiones" tabindex="-1">Pestaña Versiones <a class="header-anchor" href="#pestana-versiones" aria-label="Permalink to &quot;Pestaña Versiones&quot;">​</a></h2><p><img src="'+c+'" alt="workflows-versoes"></p><p>Cada guardado conserva una versión del workflow. La pestaña lista las versiones, permite <strong>comparar</strong> dos (en high-code, con el diff línea a línea) y <strong>restaurar</strong> una anterior.</p><p>Restaurar no borra nada: crea una versión nueva con el contenido antiguo. Nunca se pierde el camino de vuelta.</p><h2 id="ejecuciones" tabindex="-1">Ejecuciones <a class="header-anchor" href="#ejecuciones" aria-label="Permalink to &quot;Ejecuciones {#ejecuciones}&quot;">​</a></h2><p><img src="'+i+'" alt="execucoes-lista"></p><p>Pantalla propia, en el menú Principal: el monitor de <strong>todas</strong> las ejecuciones de la plataforma, y no de un solo workflow.</p><p>El filtro es por descripción del workflow, situación y periodo. Mientras haya ejecución activa, la lista se actualiza sola cada pocos segundos — y un indicador arriba muestra que está acompañando.</p><p>Las situaciones son:</p><table tabindex="0"><thead><tr><th>Situación</th><th>Qué significa</th></tr></thead><tbody><tr><td><strong>En ejecución</strong></td><td>Corriendo ahora.</td></tr><tr><td><strong>Concluida</strong></td><td>Terminó sin error.</td></tr><tr><td><strong>Con error</strong></td><td>Terminó con excepción. El mensaje está en el detalle.</td></tr><tr><td><strong>Cancelando</strong></td><td>Cancelación pedida; esperando que el proceso llegue a un punto de parada.</td></tr><tr><td><strong>Cancelada</strong></td><td>Paró por pedido del usuario.</td></tr><tr><td><strong>Interrumpida</strong></td><td>El proceso que la ejecutaba dejó de responder.</td></tr></tbody></table><p><strong>Interrumpida</strong> merece atención: no es un error de tu workflow, es el proceso que murió (contenedor reiniciado, máquina apagada). La plataforma lo marca así cuando una ejecución deja de dar señales de vida por algunos minutos, para no dejar un registro atrapado en &quot;en ejecución&quot; para siempre.</p><p><img src="'+d+'" alt="execucoes-detalhe"></p><p>El detalle trae el origen (manual, agendada, webhook o API), quién la disparó, la duración, el nodo actual, una vista previa de la salida y el log completo.</p><h3 id="cancelar" tabindex="-1">Cancelar <a class="header-anchor" href="#cancelar" aria-label="Permalink to &quot;Cancelar&quot;">​</a></h3><p>El botón de cancelar funciona <strong>también cuando la ejecución la disparó el agendador</strong>, en otro proceso — el pedido se graba en la base y el proceso que está ejecutando lo lee en segundos.</p><p>En low-code, la cancelación se comprueba entre un nodo y otro: un nodo ya iniciado termina. En high-code, depende de tu <code>is_cancelled()</code>.</p>',42)])])}const k=e(u,[["render",p]]);export{j as __pageData,k as default};
